ystems projects.","policies":{"privacy":{"title":"Privacy Policy","intro":"Owner review required: this is a draft describing the current website. The owner must confirm retention periods, request handling and provider arrangements before publishing the final policy.","sections":[["Information we collect","Orders collect your name, email, phone number, delivery choice and address when delivery is requested. Bookings also collect device information, the reported problem, requested schedule, service mode and onsite address when applicable. Project inquiries collect requirements, hardware needs, budget range, optional target date and reference link. Contact messages collect your name, email and message. Please avoid sending passwords or unnecessary sensitive information."],["How information is used","Two Tech uses your information to respond, review requirements, arrange requested services, prepare quotations, fulfil orders and verify manual transfers. We do not collect card numbers or card security codes. Do not send card details through any form."],["Providers and storage","Netlify hosts the website and API and receives a copy of submitted orders and inquiries through Netlify Forms for owner notifications. Neon stores the records shown in the administrator Inbox, and Cloudinary stores product images. The owner may receive these submission details by email through Netlify notifications. The owner must confirm retention and access arrangements for these copies, and any additional parties involved in delivery."],["Browser storage and access","Your browser stores product IDs and quantities for your cart and a short submission throttle. Administrator access uses a secure session cookie. Access to order and inquiry records is restricted to authenticated administrators."],["Retention and requests","Owner to confirm: how long orders, bookings, quotations, messages and security records are retained, and how deletion or correction requests are handled. Contact Two Tech using the details below to ask about your information."],["Changes to this notice","The owner should review and update this notice when the website, providers or data-handling practices change."]]},"terms":{"title":"Orders & Returns","intro":"Owner review required: this draft explains the current ordering process. The owner must complete the policy items marked below; they are not promises about unconfirmed services or return rights.","sections":[["Order requests and prices","Submitting checkout creates an order received reference. It does not mean the order is paid or confirmed for fulfilment. The server checks product availability, stock, current prices and the configured delivery fee when the order is submitted. Two Tech will contact you regarding the next steps."],["Payment methods","Payment is Cash on Pickup/Delivery or manual Bank/GCash transfer. No card payment is collected or processed on this website. For a transfer, follow the current payment instructions shown at checkout. The administrator marks payment only after verifying it."],["Pickup, delivery and reservations","Pickup is free; the configured delivery fee is displayed before submission. Owner to confirm: delivery coverage, lead times, reservation duration, payment deadline and arrangements for missed pickup or unavailable customers."],["Repairs and project quotations","Bookings are schedule requests until Two Tech confirms them. Repair estimates depend on inspection, device condition, parts and agreed scope. Project requirements are reviewed before a quotation is provided. No work or price commitment is implied solely by submitting a request."],["Cancellations, returns and refunds","Owner to confirm: cancellation procedure, return eligibility, time limits, condition requirements, proof of purchase, shipping responsibilities and refund process. Contact Two Tech before returning any item. This draft does not establish a warranty or return guarantee."],["Device handling and software","Owner to confirm: repair authorization, data-backup responsibilities, device collection, parts handling and any applicable service terms. Software setup requires appropriately licensed software."]]}}}'::jsonb || public.settings.data;

alter table public.bookings drop constraint bookings_preferred_time_check;
alter table public.bookings add constraint bookings_preferred_time_length check(char_length(trim(preferred_time)) between 1 and 150);
alter table public.quotes drop constraint quotes_category_check;
alter table public.quotes add constraint quotes_category_length check(char_length(trim(category)) between 1 and 150);

create or replace function public.validate_booking_service() returns trigger language plpgsql set search_path='' as $$
declare config jsonb; valid_service boolean;
begin
 -- Historical bookings remain manageable after the catalog changes.
 if TG_OP='UPDATE' and new.service is not distinct from old.service and new.mode is not distinct from old.mode and new.preferred_time is not distinct from old.preferred_time then return new; end if;
 select data into config from public.settings where id=1;
 select exists(select 1 from pg_catalog.jsonb_array_elements(config->'services') g
   where g->>'id' in ('setup','repair','soft','clean','net') and (g->>'visible')::boolean
   and exists(select 1 from pg_catalog.jsonb_array_elements(g->'items') i where i->>'name'=new.service)
   and (g->'modes') ? new.mode) into valid_service;
 if not valid_service or not coalesce((config->'booking_times') ? new.preferred_time,false) then raise exception 'Choose a current service, supported mode and time'; end if;
 return new;
end $$;

create function public.validate_quote_choices() returns trigger language plpgsql set search_path='' as $$
declare config jsonb;
begin
 if TG_OP='UPDATE' and new.category is not distinct from old.category and new.budget is not distinct from old.budget then return new; end if;
 select data into config from public.settings where id=1;
 if not coalesce((config->'quote_categories') ? new.category,false) or not coalesce((config->'quote_budgets') ? new.budget,false) then raise exception 'Choose a current category and budget'; end if;
 return new;
end $$;
create trigger quote_choices before insert or update on public.quotes for each row execute function public.validate_quote_choices();


